import React, { useContext, useEffect, useState } from "react";
import classes from "./UserForm.module.css";
import PasswordContext from "../store/password-context";

const UserForm = () => {
  const usePassword = useContext(PasswordContext);
  const [title, setTitle] = useState("");
  const [password, setPassword] = useState("");

  // Populate form fields with editingItem details when it changes
  useEffect(() => {
    if (usePassword.editItem) {
      setTitle(usePassword.editItem.title);
      setPassword(usePassword.editItem.password);
    } else {
      setTitle("");
      setPassword("");
    }
  }, [usePassword.editItem]);

  const submitHandler = (event) => {
    event.preventDefault();
    const titleInput = event.target.elements.title;
    const passwordInput = event.target.elements.password;

    // Check if editingItem is present to determine if it's an edit or add operation
    if (usePassword.editItem) {
      // Update the item with the new values
      const updatedItem = {
        id: usePassword.editingItem.id,
        title: titleInput.value,
        password: passwordInput.value,
      };
      // Call the editItem function to update the item
      usePassword.editItem(updatedItem);
    } else {
      // Generate a unique id for the new item
      const id = Date.now() + Math.random().toString(36).substring(2);
      // Create a new item object
      const newItem = {
        id: id,
        title: titleInput.value,
        password: passwordInput.value,
      };
      // Call the addItem function to add the new item
      usePassword.addItem(newItem);
    }

    // Close the form
    usePassword.closeForm();
  };

  const closeFormhandler = () => {
    usePassword.closeForm();
  };

  return (
    <div>
      <div className={classes.form}>
        <form onSubmit={submitHandler}>
          <label>Title :</label>
          <input
            type="text"
            name="title"
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            required
          ></input>
          <label>Password:</label>
          <input
            type="text"
            name="password"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            required
          ></input>

          <button type="submit">Add</button>
          <button onClick={closeFormhandler}>X</button>
        </form>
      </div>
    </div>
  );
};

export default UserForm;
